// Mensagens do MQTT são dados não confiáveis: valida tudo e descarta o que não bate.
const SECTORS = ['N', 'NE', 'E', 'SE', 'S', 'SO', 'O', 'NO'];
const int = (v, lo, hi) => (Number.isFinite(v) && v >= lo && v <= hi ? Math.round(v) : null);
const out = [];
for (const item of $input.all()) {
  const m = String(item.json.topic || '').match(/^sound\/(inference|status)\/([A-Za-z0-9._-]{1,64})$/);
  if (!m) continue;
  let p;
  try { p = JSON.parse(String(item.json.message)); } catch (e) { continue; }
  if (typeof p !== 'object' || p === null || Array.isArray(p)) continue;
  const device_id = m[2];
  if (m[1] === 'status') {
    out.push({ json: { kind: 'status', device_id, uptime_s: int(p.uptime_s, 0, 4e9), heap: int(p.heap, 0, 4e9), rssi: int(p.rssi, -127, 0), raw_json: JSON.stringify(p) } });
    continue;
  }
  if (p.mock === true) continue; // leituras simuladas nunca entram no banco
  const label = typeof p.label === 'string' ? p.label : '';
  const conf = Number(p.confidence);
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(label) || !(conf >= 0 && conf <= 1)) continue;
  const doa = Number(p.doa_confidence);
  out.push({ json: {
    kind: 'inference', device_id, label, confidence: conf,
    direction_deg: int(p.direction_deg, 0, 359),
    sector: SECTORS.includes(p.sector) ? p.sector : null,
    doa_confidence: p.doa_confidence !== undefined && doa >= 0 && doa <= 1 ? doa : null,
    raw_json: JSON.stringify(p),
  } });
}
return out;

