VALUES ($1, $2, $3, $4::smallint, $5::text, $6::float4, (SELECT urgency FROM sound_classes WHERE label = $2), $7::jsonb)
RETURNING device_id, label, confidence, sector, urgency;

WITH d AS (INSERT INTO devices (device_id) VALUES ($1) ON CONFLICT (device_id) DO NOTHING)
INSERT INTO device_status (device_id, uptime_s, heap, rssi, raw_json)
VALUES ($1, $2::bigint, $3::bigint, $4::smallint, $5::jsonb);

