// Assina o alerta para o Hermes (HMAC-SHA256 de "<timestamp>.<corpo>", cabeçalho V2).
// Precisa de NODE_FUNCTION_ALLOW_BUILTIN=crypto e HERMES_WEBHOOK_SECRET no n8n (docker-compose.yaml).
const crypto = require('crypto');
const d = $input.first().json;
const body = JSON.stringify({
  label: d.label,
  confidence_pct: Math.round(d.confidence * 100),
  device: d.device_id,
  sector: d.sector || 'não estimada',
  urgency: d.urgency,
});
const ts = String(Math.floor(Date.now() / 1000));
const sig = crypto.createHmac('sha256', $env.HERMES_WEBHOOK_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, ts, sig } }];
